C_BG_DARK     = RGBColor(15, 23, 42)
C_BG_LIGHT    = RGBColor(248, 250, 252)
C_CARD_WHITE  = RGBColor(255, 255, 255)
C_BORDER      = RGBColor(203, 213, 225)
C_NAVY        = RGBColor(30, 27, 75)
C_PRIMARY     = RGBColor(79, 70, 229)
C_CYAN        = RGBColor(6, 182, 212)
C_EMERALD     = RGBColor(16, 185, 129)
C_AMBER       = RGBColor(245, 158, 11)
C_ROSE        = RGBColor(239, 68, 68)
C_TEXT_DARK   = RGBColor(15, 23, 42)
C_TEXT_MUTED  = RGBColor(100, 116, 139)
C_WHITE      = RGBColor(255, 255, 255)


def add_slide_header(slide, title, category="CONTROLPLANE.AI -- FLOWCHART ARCHITECTURE  PITCH"):
    tb_cat = slide.shapes.add_textbox(Inches(0.6), Inches(0.35), Inches(12.13), Inches(0.25))
    tf_c = tb_cat.text_frame
    p_c = tf_c.paragraphs[0]
    p_c.text = category.upper()
    p_c.font.name = "Arial"
    p_c.font.size = Pt(9)
    p_c.font.bold = True
    p_c.font.color.rgb = C_PRIMARY

    tb_title = slide.shapes.add_textbox(Inches(0.6), Inches(0.60), Inches(12.13), Inches(0.55))
    tf_t = tb_title.text_frame
    p_t = tf_t.paragraphs[0]
    p_t.text = title
    p_t.font.name = "Arial"
    p_t.font.size = Pt(18)
    p_t.font.bold = True
    p_t.font.color.rgb = C_NAVY


def add_flow_node(slide, left, top, width, height, title, subtitle="", bg_color=C_CARD_WHITE, border_color=C_BORDER, header_color=C_PRIMARY, text_color=C_TEXT_DARK, shape_type=MSO_SHAPE.ROUNDED_RECTANGLE):
    node = slide.shapes.add_shape(shape_type, left, top, width, height)
    node.fill.solid()
    node.fill.fore_color.rgb = bg_color
    node.line.color.rgb = border_color
    node.line.width = Pt(1.5)
    
    tb = slide.shapes.add_textbox(left + Inches(0.1), top + Inches(0.1), width - Inches(0.2), height - Inches(0.2))
    tf = tb.text_frame
    tf.word_wrap = True
    p1 = tf.paragraphs[0]
    p1.text = title
    p1.font.name = "Arial"
    p1.font.size = Pt(10)
    p1.font.bold = True
    p1.font.color.rgb = header_color
    p1.alignment = PP_ALIGN.CENTER
    if subtitle:
        p2 = tf.add_paragraph()
        p2.text = subtitle
        p2.font.name = "Arial"
        p2.font.size = Pt(8.5)
        p2.font.color.rgb = text_color
        p2.alignment = PP_ALIGN.CENTER
        p2.space_before = Pt(2)
    return node


def add_arrow_label(slide, left, top, width, height, text="", arrow_color=C_PRIMARY):
    arrow = slide.shapes.add_shape(MSO_SHAPE.RIGHT_ARROW, left, top, width, height)
    arrow.fill.solid()
    arrow.fill.fore_color.rgb = arrow_color
    arrow.line.fill.background()
    if text:
        tf = arrow.text_frame
        p = tf.paragraphs[0]
        p.text = text
        p.font.name = "Arial"
        p.font.size = Pt(8)
        p.font.bold = True
        p.font.color.rgb = C_WHITE
        p.alignment = PP_ALIGN.CENTER
    return arrow


